import{_ as t,o as d,c as a,Q as e}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"日期、星期、月份与季节","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/grammar/07-dates.md","filePath":"zh/more/maltese/grammar/07-dates.md"}'),r={name:"zh/more/maltese/grammar/07-dates.md"},i=e('<h1 id="日期、星期、月份与季节" tabindex="-1">日期、星期、月份与季节 <a class="header-anchor" href="#日期、星期、月份与季节" aria-label="Permalink to &quot;日期、星期、月份与季节&quot;">​</a></h1><h2 id="_1-星期几" tabindex="-1">1. 星期几 <a class="header-anchor" href="#_1-星期几" aria-label="Permalink to &quot;1. 星期几&quot;">​</a></h2><table><thead><tr><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>星期一</td><td>Monday</td><td>it-Tnejn</td></tr><tr><td>星期二</td><td>Tuesday</td><td>it-Tlieta</td></tr><tr><td>星期三</td><td>Wednesday</td><td>l-Erbgħa</td></tr><tr><td>星期四</td><td>Thursday</td><td>il-Ħamis</td></tr><tr><td>星期五</td><td>Friday</td><td>il-Ġimgħa</td></tr><tr><td>星期六</td><td>Saturday</td><td>is-Sibt</td></tr><tr><td>星期日</td><td>Sunday</td><td>il-Ħadd</td></tr></tbody></table><p>星期前常用 <code>nhar</code>（某一天），例如 <code>nhar it-Tnejn</code>（星期一这一天）。具体表达中常保留定冠词。</p><h2 id="_2-月份" tabindex="-1">2. 月份 <a class="header-anchor" href="#_2-月份" aria-label="Permalink to &quot;2. 月份&quot;">​</a></h2><table><thead><tr><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>一月</td><td>January</td><td>Jannar</td></tr><tr><td>二月</td><td>February</td><td>Frar</td></tr><tr><td>三月</td><td>March</td><td>Marzu</td></tr><tr><td>四月</td><td>April</td><td>April</td></tr><tr><td>五月</td><td>May</td><td>Mejju</td></tr><tr><td>六月</td><td>June</td><td>Ġunju</td></tr><tr><td>七月</td><td>July</td><td>Lulju</td></tr><tr><td>八月</td><td>August</td><td>Awwissu</td></tr><tr><td>九月</td><td>September</td><td>Settembru</td></tr><tr><td>十月</td><td>October</td><td>Ottubru</td></tr><tr><td>十一月</td><td>November</td><td>Novembru</td></tr><tr><td>十二月</td><td>December</td><td>Diċembru</td></tr></tbody></table><p>月份前常用 <code>f&#39;</code>，如 <code>f&#39;Mejju</code>（在五月）、<code>f&#39;Ġunju</code>（在六月）。月份名称在句中通常按普通名词书写；本表统一首字母大写以便查找。</p><h2 id="_3-季节、年份与相对日期" tabindex="-1">3. 季节、年份与相对日期 <a class="header-anchor" href="#_3-季节、年份与相对日期" aria-label="Permalink to &quot;3. 季节、年份与相对日期&quot;">​</a></h2><table><thead><tr><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>春天</td><td>spring</td><td>rebbiegħa</td></tr><tr><td>夏天</td><td>summer</td><td>sajf</td></tr><tr><td>秋天</td><td>autumn; fall</td><td>ħarifa</td></tr><tr><td>冬天</td><td>winter</td><td>xitwa</td></tr><tr><td>年</td><td>year</td><td>sena</td></tr><tr><td>明年</td><td>next year</td><td>is-sena d-dieħla</td></tr><tr><td>去年</td><td>last year</td><td>is-sena l-oħra</td></tr></tbody></table><p>季节前常见形式：<code>fir-rebbiegħa</code>（在春天）、<code>fis-sajf</code>（在夏天）、<code>fil-ħarifa</code>（在秋天）、<code>fix-xitwa</code>（在冬天）。年份可以用数字书写，如 <code>fl-2026</code>（在 2026 年）。</p><h3 id="上-本-下周、月、年" tabindex="-1">上/本/下周、月、年 <a class="header-anchor" href="#上-本-下周、月、年" aria-label="Permalink to &quot;上/本/下周、月、年&quot;">​</a></h3><table><thead><tr><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>上周</td><td>last week</td><td>il-ġimgħa li għaddiet</td></tr><tr><td>本周/这周</td><td>this week</td><td>din il-ġimgħa</td></tr><tr><td>下周</td><td>next week</td><td>il-ġimgħa d-dieħla</td></tr><tr><td>上个月</td><td>last month</td><td>ix-xahar li għadda</td></tr><tr><td>本月/这个月</td><td>this month</td><td>dan ix-xahar</td></tr><tr><td>下个月</td><td>next month</td><td>ix-xahar id-dieħel</td></tr><tr><td>去年</td><td>last year</td><td>is-sena l-oħra</td></tr><tr><td>今年</td><td>this year</td><td>din is-sena</td></tr><tr><td>明年</td><td>next year</td><td>is-sena d-dieħla</td></tr></tbody></table><p><code>li għadda</code> 表示“刚过去的/上一个”，<code>li jmiss</code> 可表示“下一个”，而 <code>d-dieħel</code> 常用于将来的月份或年份表达。相对时间词通常和上下文中的动词时态一起理解。</p><h2 id="_4-日期表达方式" tabindex="-1">4. 日期表达方式 <a class="header-anchor" href="#_4-日期表达方式" aria-label="Permalink to &quot;4. 日期表达方式&quot;">​</a></h2><p>星期、月份、季节前置时间介词时，介词常与定冠词缩合。常见日期顺序是“日 + <code>ta&#39;</code> + 月份 + 年份”，例如 <code>14 ta&#39; Ottubru 2026</code>（2026 年 10 月 14 日）；星期可用 <code>nhar</code> 引出，如 <code>nhar it-Tnejn</code>（星期一这一天）。为避免不同国家的日/月顺序造成误解，正式行程建议写月份全名。谈论某周、某月或某年时，可直接使用上表的相对时间短语。</p><h2 id="_5-20-个日期例句" tabindex="-1">5. 20 个日期例句 <a class="header-anchor" href="#_5-20-个日期例句" aria-label="Permalink to &quot;5. 20 个日期例句&quot;">​</a></h2><table><thead><tr><th style="text-align:right;">#</th><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>星期一我去学校。</td><td>On Monday I go to school.</td><td>Nhar it-Tnejn immur l-iskola.</td></tr><tr><td style="text-align:right;">2</td><td>星期二我在家工作。</td><td>On Tuesday I work at home.</td><td>Nhar it-Tlieta naħdem id-dar.</td></tr><tr><td style="text-align:right;">3</td><td>星期三我读一本书。</td><td>On Wednesday I read a book.</td><td>Nhar l-Erbgħa naqra ktieb.</td></tr><tr><td style="text-align:right;">4</td><td>星期四我买面包。</td><td>On Thursday I buy bread.</td><td>Nhar il-Ħamis nixtri l-ħobż.</td></tr><tr><td style="text-align:right;">5</td><td>星期五我和朋友见面。</td><td>On Friday I meet a friend.</td><td>Nhar il-Ġimgħa niltaqa&#39; ma&#39; ħabib.</td></tr><tr><td style="text-align:right;">6</td><td>星期六我去海边。</td><td>On Saturday I go to the beach.</td><td>Nhar is-Sibt immur il-bajja.</td></tr><tr><td style="text-align:right;">7</td><td>星期日我休息。</td><td>On Sunday I rest.</td><td>Nhar il-Ħadd nistrieħ.</td></tr><tr><td style="text-align:right;">8</td><td>一月我穿外套。</td><td>In January I wear a coat.</td><td>F&#39;Jannar nilbes kowt.</td></tr><tr><td style="text-align:right;">9</td><td>二月有二十八天。</td><td>February has twenty-eight days.</td><td>Frar għandu tmienja u għoxrin jum.</td></tr><tr><td style="text-align:right;">10</td><td>三月春天开始。</td><td>Spring begins in March.</td><td>F&#39;Marzu tibda r-rebbiegħa.</td></tr><tr><td style="text-align:right;">11</td><td>四月我们看花。</td><td>In April we see flowers.</td><td>F&#39;April naraw il-fjuri.</td></tr><tr><td style="text-align:right;">12</td><td>五月我探望家人。</td><td>In May I visit my family.</td><td>F&#39;Mejju nżur lill-familja tiegħi.</td></tr><tr><td style="text-align:right;">13</td><td>六月夏天开始。</td><td>Summer begins in June.</td><td>F&#39;Ġunju jibda s-sajf.</td></tr><tr><td style="text-align:right;">14</td><td>七月我去马耳他。</td><td>In July I go to Malta.</td><td>F&#39;Lulju mmur Malta.</td></tr><tr><td style="text-align:right;">15</td><td>十二月我们庆祝圣诞节。</td><td>In December we celebrate Christmas.</td><td>F&#39;Diċembru niċċelebraw il-Milied.</td></tr><tr><td style="text-align:right;">16</td><td>我会在 2026 年 10 月 14 日开始上课。</td><td>I will start lessons on 14 October 2026.</td><td>Nibda l-lezzjonijiet fl-14 ta&#39; Ottubru 2026.</td></tr><tr><td style="text-align:right;">17</td><td>上周我拜访了家人。</td><td>I visited my family last week.</td><td>Il-ġimgħa li għaddiet żort lill-familja tiegħi.</td></tr><tr><td style="text-align:right;">18</td><td>这周我们在家学习。</td><td>We are studying at home this week.</td><td>Din il-ġimgħa qed nitgħallmu d-dar.</td></tr><tr><td style="text-align:right;">19</td><td>下个月我去马耳他。</td><td>I am going to Malta next month.</td><td>Ix-xahar id-dieħel immur Malta.</td></tr><tr><td style="text-align:right;">20</td><td>明年我们会搬家。</td><td>We will move house next year.</td><td>Is-sena d-dieħla se niċċaqilqu.</td></tr></tbody></table>',17),l=[i];function n(h,o,s,g,u,m){return d(),a("div",null,l)}const y=t(r,[["render",n]]);export{b as __pageData,y as default};
